import sys
from z3 import *

solver = Solver()
faces = [[Int(f'f_{i}_{j}') for j in range(6)] for i in range(5)]

for i in range(5):
    for j in range(6):
        solver.add(faces[i][j] >= 0, faces[i][j] <= 11)
    for j in range(5):
        solver.add(faces[i][j] <= faces[i][j+1])

# Symmetry breaking
solver.add(faces[0][0] == 0)

def count_wins(A, B):
    return Sum([If(a > b, 1, 0) for a in A for b in B])

for i in range(5):
    next_i = (i + 1) % 5
    solver.add(count_wins(faces[i], faces[next_i]) >= 19)

if solver.check() == sat:
    m = solver.model()
    res = []
    for i in range(5):
        die = []
        for j in range(6):
            die.append(m[faces[i][j]].as_long())
        res.extend(die)
    print(res)
else:
    print("UNSATISFIABLE")
